/**
 * The source of a CloudFront Function (runtime `cloudfront-js-2.0`, viewer
 * request) that answers a path ending in `/`, other than `/` itself, with a
 * permanent redirect to the same path without its trailing slashes, keeping
 * the query string. Kept as source text, so the spec runs exactly the code
 * that is deployed.
 */
export const TRAILING_SLASH_REDIRECT_SOURCE = `
function handler(event) {
  var request = event.request;
  var uri = request.uri;
  if (uri.length < 2 || uri.charAt(uri.length - 1) !== '/') {
    return request;
  }
  var path = uri.replace(/\\/+$/, '') || '/';
  var query = Object.keys(request.querystring).flatMap(function (key) {
    var entry = request.querystring[key];
    var values = entry.multiValue
      ? entry.multiValue.map(function (item) { return item.value; })
      : [entry.value];
    return values.map(function (value) { return key + '=' + value; });
  });
  return {
    statusCode: 301,
    statusDescription: 'Moved Permanently',
    headers: {
      location: { value: query.length ? path + '?' + query.join('&') : path },
    },
  };
}
`;
